def vector_retrieve(query):
    # one of the tools the agent can choose
    return "The Falcon plan costs twenty dollars per month."

def web_search(query):
    # another tool the agent can choose
    return "Falcon plan pricing was last updated this quarter."

def is_information_sufficient(gathered):
    # check whether gathered information is sufficient
    return any("costs" in item for item in gathered)

def agentic_rag(query, max_steps=4):
    # bound the loop with a maximum step count
    gathered = []
    tools = [vector_retrieve, web_search]
    for step in range(max_steps):
        tool = tools[step % len(tools)]
        result = tool(query)
        gathered.append(result)
        if is_information_sufficient(gathered):
            return {"steps_taken": step + 1, "gathered": gathered, "stopped_early": True}
    return {"steps_taken": max_steps, "gathered": gathered, "stopped_early": False}

result = agentic_rag("What does the Falcon plan cost?")
print("Agentic RAG result:")
print(result)
